cheatsheet.c:
string path = "poem.txt";

if (File.Exists(path))
{
    Console.WriteLine("File Already Exists: " + path);
}
else
{
    try
    {
        File.WriteAllText(path, "Первая строка");
        Console.WriteLine("File Written: " + path);
    }
    catch (Exception error)
    {
        Console.WriteLine(error.Message);
    }
}

string[] poem = new string[]
{
    "Первая строка",
    "Вторая строка",
};

File.WriteAllLines(path, poem);        // перезаписать
File.AppendAllText(path, "\nХвост");   // дописать в конец

if (File.Exists(path))
{
    try
    {
        string text = File.ReadAllText(path);
        Console.WriteLine(text);

        string[] lines = File.ReadAllLines(path);
        int num = 1;
        foreach (string line in lines)
        {
            Console.WriteLine(num + " : " + line);
            num++;
        }
    }
    catch (Exception error) { Console.WriteLine(error.Message); }
}

using (StreamWriter writer = new StreamWriter(path))
{
    foreach (string line in poem)
    { writer.WriteLine(line); }
}

// второй аргумент true — режим дописывания
using (StreamWriter writer = new StreamWriter(path, true))
{
    writer.WriteLine("Дописанная строка");
}

using (StreamReader reader = new StreamReader(path))
{
    string line;
    while ((line = reader.ReadLine()) != null)
    {
        string[] sub = line.Split(',');
        Console.WriteLine(String.Format("{0,-30} {1,-20}", sub[0], sub[1]));
    }
}

